export const TEAM_REFLECTION_ACTIVITIES = [
// FASE A — FONDASI / KONKRET (1-20): apa itu refleksi tim, kapan, apa yang ditanya
{n:1,type:"mcq",micro:"Apa itu refleksi tim",q:"'Refleksi tim' (evaluasi) adalah...",options:["Meninjau bersama bagaimana tim bekerja: apa yang berjalan baik, apa yang bisa lebih baik, & apa yang akan diubah","Mencari siapa yang paling banyak salah","Merayakan tanpa membahas apa pun"],answer:0,explain:"Refleksi tim berfokus pada belajar & memperbaiki cara kerja, bukan menyalahkan orang.",hint:"Meninjau cara kerja & belajar, atau mencari yang salah?"},
{n:2,type:"mcq",micro:"Kenapa refleksi",q:"Manfaat utama merefleksikan tim setelah (atau di tengah) proyek:",options:["Membuat semua orang merasa bersalah","Tim membawa pelajaran ke proyek berikutnya & menjadi makin efektif","Membuang waktu, proyek sudah selesai"],answer:1,explain:"Tanpa refleksi, tim cenderung mengulang kesalahan yang sama. Dengan refleksi, tiap proyek menaikkan kemampuan tim.",hint:"Membawa pelajaran ke depan, atau buang waktu?"},
{n:3,type:"mcq",micro:"Kapan refleksi dilakukan",q:"Refleksi tim paling berguna dilakukan...",options:["Hanya kalau proyek gagal","Tidak pernah","Di titik tengah proyek (untuk menyesuaikan) & di akhir (untuk belajar) — bukan hanya kalau ada masalah besar"],answer:2,explain:"Refleksi tengah bisa menyelamatkan proyek yang menyimpang; refleksi akhir membangun tim untuk masa depan.",hint:"Tengah + akhir, atau hanya saat gagal?"},
{n:4,type:"mcq",micro:"Tiga pertanyaan dasar",q:"Kerangka refleksi tim yang sederhana & efektif:",options:["Apa yang berjalan baik? Apa yang menghambat/kurang? Apa satu-dua hal yang akan kita ubah lain kali?","Siapa yang paling malas? Siapa yang paling rajin?","Apakah kita menang atau kalah?"],answer:0,explain:"'Baik / kurang / ubah' menjaga refleksi seimbang & berorientasi perbaikan.",hint:"Baik/kurang/ubah, atau siapa malas/rajin?"},
{n:5,type:"mcq",micro:"Fokus pada proses, bukan orang",q:"Refleksi tim yang sehat fokus pada...",options:["Memuji satu orang saja","Sistem & proses kerja ('briefing kita kurang jelas', 'tidak ada cek kemajuan'), bukan menyalahkan individu","Mencari kambing hitam"],answer:1,explain:"'Apa yang bisa kita perbaiki sebagai tim?' jauh lebih produktif daripada 'siapa yang salah?'.",hint:"Sistem & proses, atau kambing hitam?"},
{n:6,type:"mcq",micro:"Menyebut yang berjalan baik",q:"Dalam refleksi, membahas apa yang SUDAH berjalan baik berguna karena...",options:["Membuang waktu, hanya masalah yang penting","Membuat tim sombong","Tim tahu kekuatan apa yang harus dipertahankan, & refleksi tidak terasa hanya berisi keluhan"],answer:2,explain:"Refleksi yang hanya berisi kritik terasa melelahkan & tidak lengkap. Menyebut kekuatan menjaga keseimbangan.",hint:"Tahu yang harus dipertahankan, atau buang waktu?"},
{n:7,type:"mcq",micro:"Refleksi & rasa aman",q:"Agar anggota jujur saat refleksi, penting bahwa...",options:["Menyampaikan kritik atau mengakui kesalahan tidak akan membuat mereka dihina atau dimusuhi","Semua takut sehingga cepat setuju","Hanya ketua yang boleh bicara"],answer:0,explain:"Refleksi dalam suasana takut hanya menghasilkan 'semua baik-baik saja' yang tidak berguna.",hint:"Aman untuk jujur, atau takut?"},
{n:8,type:"mcq",micro:"Refleksi menghasilkan tindakan",q:"Refleksi tim yang efektif diakhiri dengan...",options:["Perasaan lega tanpa kesimpulan","Satu-dua perubahan konkret yang akan diterapkan, dengan siapa & kapan — bukan hanya obrolan yang dilupakan","Daftar panjang keluhan tanpa rencana"],answer:1,explain:"Refleksi yang tidak menghasilkan perubahan nyata hanya sesi curhat. Akhiri dengan aksi.",hint:"1-2 perubahan konkret, atau obrolan yang dilupakan?"},
{n:9,type:"order",micro:"Menjalankan refleksi tim",q:"Urutkan langkah sesi refleksi tim 20 menit.",items:["Sepakati tujuan & aturan: fokus pada proses & perbaikan, bukan menyalahkan orang","Tiap anggota menyebut apa yang berjalan baik & apa yang menghambat","Kelompokkan poin yang mirip; pilih 1-2 hal terpenting untuk diperbaiki","Sepakati perubahan konkret + siapa + kapan; catat","Akhiri dengan mengapresiasi usaha tim"],answer:[0,1,2,3,4],explain:"Aturan → kumpulkan poin → pilih prioritas → tindakan konkret → apresiasi. Struktur menjaga refleksi produktif & positif.",hint:"Apa yang disepakati sebelum mengumpulkan poin?"},
{n:10,type:"mcq",micro:"Refleksi diri dalam tim",q:"Selain merefleksikan tim, tiap anggota juga bisa merefleksikan...",options:["Kesalahan anggota lain saja","Tidak perlu refleksi diri","Kontribusinya sendiri: apakah aku menepati bagianku? membantu? mendengar? apa yang akan kuperbaiki?"],answer:2,explain:"Menilai peran sendiri secara jujur (bukan hanya menilai orang lain) mempercepat kamu jadi anggota tim yang lebih baik.",hint:"Kontribusi sendiri juga, atau hanya menilai orang lain?"},
{n:11,type:"tf",micro:"Refleksi bukan sesi menyalahkan",q:"Benar atau Salah: Refleksi tim yang baik berfokus pada 'apa yang bisa kita perbaiki sebagai tim', bukan pada 'siapa yang paling bersalah'.",answer:true,explain:"Refleksi yang berubah jadi sesi menyalahkan membuat orang defensif & menyembunyikan masalah di lain waktu.",hint:"Perbaikan tim, atau mencari yang bersalah?"},
{n:12,type:"tf",micro:"Refleksi hanya kalau gagal?",q:"Benar atau Salah: Refleksi tim hanya perlu dilakukan ketika sebuah proyek gagal — kalau proyek berhasil, tidak ada yang perlu dibahas.",answer:false,explain:"Sebaliknya, proyek yang berhasil pun punya pelajaran: apa yang membuatnya berhasil (agar diulang), & apa yang tetap bisa lebih baik. Refleksi setelah sukses menguatkan kebiasaan baik.",hint:"Hanya saat gagal, atau juga setelah berhasil?"},
{n:13,type:"mcq",micro:"Refleksi tengah proyek",q:"Refleksi di titik tengah proyek berguna terutama untuk...",options:["Menyesuaikan rencana, pembagian tugas, atau cara kerja SELAGI masih ada waktu memperbaiki","Menilai hasil akhir","Merayakan"],answer:0,explain:"Refleksi tengah adalah kesempatan menyelamatkan proyek yang menyimpang sebelum terlambat.",hint:"Menyesuaikan selagi ada waktu, atau menilai hasil akhir?"},
{n:14,type:"mcq",micro:"Refleksi & catatan",q:"Menuliskan hasil refleksi (apa yang dipelajari, apa yang akan diubah) berguna karena...",options:["Tidak ada gunanya","Menjadi acuan agar pelajaran benar-benar diterapkan di proyek berikutnya, bukan dilupakan","Membuat tim terlalu formal"],answer:1,explain:"Pelajaran yang tidak ditulis sering menguap. Catatan singkat membuatnya bertahan.",hint:"Acuan untuk diterapkan, atau terlalu formal?"},
{n:15,type:"mcq",micro:"Menerima kritik saat refleksi",q:"Saat refleksi & seseorang menyebut hal yang menyangkut caramu bekerja, sikap yang baik:",options:["Membela diri & menyebut kesalahan orang lain","Tersinggung & diam sepanjang sisa sesi","Dengarkan tanpa langsung defensif; anggap ini kesempatan belajar; tanyakan contoh bila perlu"],answer:2,explain:"Refleksi hanya berguna bila semua bisa menerima masukan. Defensif menghentikan pembelajaran.",hint:"Dengar & belajar, atau membela diri / tersinggung?"},
{n:16,type:"mcq",micro:"Refleksi yang seimbang",q:"Refleksi tim yang baik menyeimbangkan...",options:["Menghargai usaha & kekuatan tim DENGAN jujur soal yang perlu diperbaiki","Hanya pujian agar semua senang","Hanya kritik agar 'serius'"],answer:0,explain:"Terlalu banyak pujian menyembunyikan masalah; terlalu banyak kritik mematahkan semangat. Seimbang.",hint:"Hargai + jujur soal perbaikan, atau hanya pujian / hanya kritik?"},
{n:17,type:"mcq",micro:"Refleksi & anggota pendiam",q:"Agar refleksi mendengar semua (bukan hanya yang vokal), cara yang membantu:",options:["Anggap yang diam berarti tidak punya masukan","Putar giliran ('semua sebut satu hal'), atau minta menulis dulu sebelum diskusi, atau tanyakan anggota pendiam secara khusus","Biarkan yang mau bicara saja"],answer:1,explain:"Anggota pendiam sering menyimpan pengamatan berharga. Refleksi butuh usaha sengaja untuk mendengar mereka.",hint:"Putar giliran / tulis dulu / tanya khusus, atau biarkan?"},
{n:18,type:"mcq",micro:"Refleksi vs perayaan",q:"Merayakan keberhasilan & merefleksikan pelajaran...",options:["Hanya perlu salah satu","Perayaan membuat refleksi tidak perlu","Keduanya penting & bisa dilakukan bersamaan: apresiasi usaha semua + bahas apa yang bisa lebih baik"],answer:2,explain:"Merayakan menjaga semangat; merefleksikan menjaga pertumbuhan. Tim yang sehat melakukan keduanya.",hint:"Keduanya bersamaan, atau hanya salah satu?"},
{n:19,type:"mcq",micro:"Refleksi & pertumbuhan tim",q:"Tim yang rutin merefleksikan cara kerjanya cenderung...",options:["Bekerja lebih baik dari proyek ke proyek karena terus memperbaiki proses & saling memahami","Tetap sama selamanya","Selalu bertengkar"],answer:0,explain:"Refleksi adalah mesin pertumbuhan tim. Tim tanpa refleksi mengulang pola yang sama.",hint:"Membaik tiap proyek, atau tetap sama?"},
{n:20,type:"open",micro:"Merancang sesi refleksi",q:"Timmu (5 orang) baru menyelesaikan proyek. Hasilnya lumayan tapi prosesnya berantakan: tenggat mepet, beberapa bagian dikerjakan terburu-buru, dan dua anggota merasa bebannya tidak adil. Rancang sesi refleksi tim 20 menit: struktur, pertanyaan yang kamu ajukan, dan bagaimana kamu memastikan sesi ini menghasilkan perbaikan nyata (bukan cuma keluhan).",sample:"Struktur: (1) Buka dengan tujuan & aturan (2 menit): 'Kita review proyek kemarin bukan buat cari salah siapa, tapi biar proyek berikutnya lebih lancar. Fokus ke proses kita, bukan ke orang. Semua bicara.' (2) Kumpulkan poin (8 menit): putar giliran, tiap orang menyebut SATU hal yang berjalan baik dan SATU hal yang menghambat. Aku catat semua di satu tempat yang terlihat. Contoh pertanyaan pemandu: 'Bagian mana dari cara kerja kita yang bikin kita mepet di akhir?', 'Apakah pembagian tugas kemarin terasa adil? kenapa/kenapa tidak?', 'Kapan kita pertama sadar ada masalah, dan kenapa nggak ditangani lebih awal?'. (3) Kelompokkan & pilih prioritas (5 menit): lihat poin yang mirip (mis. banyak menyebut 'nggak ada cek kemajuan' dan 'tenggat internal nggak jelas'). Pilih 1-2 masalah terpenting untuk diperbaiki — di sini kemungkinan: (a) tidak ada tenggat internal & cek kemajuan; (b) beban tidak diseimbangkan sejak awal. (4) Sepakati perubahan konkret (4 menit): untuk (a) — 'proyek berikutnya kita bikin tenggat internal 3 hari sebelum batas + cek kemajuan tiap Rabu'; untuk (b) — 'setelah membagi tugas, kita perkirakan beban tiap bagian bareng & geser bila timpang'. Tulis: perubahan apa, siapa memastikan, mulai kapan. (5) Tutup (1 menit): apresiasi usaha semua, terutama dua anggota yang menanggung lebih. Memastikan menghasilkan perbaikan nyata: sesi diakhiri dengan CATATAN tertulis berisi 1-2 perubahan + penanggung jawab + kapan mulai; di awal proyek berikutnya, catatan itu dibuka lagi sebagai pengingat; dan di refleksi tengah proyek berikutnya, kami cek 'apakah perubahan yang kita sepakati benar-benar dijalankan?'.",explain:"Jawaban baik: struktur jelas (aturan → kumpulkan poin bergiliran → kelompokkan & pilih 1-2 prioritas → perubahan konkret + siapa + kapan → apresiasi), pertanyaan pemandu yang fokus pada proses (kenapa mepet, apakah beban adil, kenapa masalah tak ditangani dini), dan mekanisme memastikan perubahan diterapkan (catatan tertulis + penanggung jawab, dibuka lagi di proyek berikutnya, dicek di refleksi tengah).",hint:"Aturan (fokus proses) → poin bergiliran + pertanyaan pemandu → pilih 1-2 prioritas → perubahan konkret + siapa + kapan → apresiasi. Pastikan: catatan tertulis + dicek di proyek berikutnya."},

// FASE B — PEMAHAMAN (21-40)
{n:21,type:"classify",micro:"Refleksi: berguna vs tidak berguna",q:"Kelompokkan tiap pernyataan refleksi ke 'Berguna (mengarah ke perbaikan)' atau 'Tidak berguna'.",items:["'Kita telat karena tidak ada tenggat internal — lain kali kita buat.'","'Deni memang pemalas, itu masalahnya.'","'Presentasi kita kuat karena latihan bareng dua kali — pertahankan.'","'Ya gitu deh, namanya juga kerja kelompok.'"],groups:["Berguna (mengarah ke perbaikan)","Tidak berguna"],answer:{"Berguna (mengarah ke perbaikan)":["'Kita telat karena tidak ada tenggat internal — lain kali kita buat.'","'Presentasi kita kuat karena latihan bareng dua kali — pertahankan.'"],"Tidak berguna":["'Deni memang pemalas, itu masalahnya.'","'Ya gitu deh, namanya juga kerja kelompok.'"]},explain:"Berguna: menyebut penyebab proses + tindakan/pelajaran. Tidak berguna: menyalahkan pribadi, atau pasrah tanpa pelajaran.",hint:"Penyebab proses + tindakan, atau menyalahkan / pasrah?"},
{n:22,type:"mcq",micro:"Dari gejala ke akar masalah",q:"Saat refleksi menemukan 'kita selalu mepet di akhir', langkah berikutnya:",options:["Menyalahkan yang paling telat","Tanya 'kenapa?' beberapa kali untuk menemukan akar: tenggat internal tidak ada? cek kemajuan tidak rutin? bagian awal telat?","Cukup mencatat 'jangan mepet lagi'"],answer:1,explain:"'Jangan mepet lagi' bukan solusi. Menemukan penyebab (proses yang hilang) memungkinkan perbaikan nyata.",hint:"Cari akar dengan 'kenapa', atau catat gejala / menyalahkan?"},
{n:23,type:"mcq",micro:"Refleksi & data",q:"Refleksi lebih akurat bila didukung...",options:["Hanya perasaan & ingatan samar","Pendapat satu orang saja","Fakta konkret: kapan bagian selesai, berapa kali rapat batal, mana yang dikerjakan ulang — bukan hanya kesan"],answer:2,explain:"Ingatan bias. Melihat catatan/fakta selama proyek membuat refleksi lebih jujur & spesifik.",hint:"Fakta konkret, atau kesan samar / satu pendapat?"},
{n:24,type:"mcq",micro:"Refleksi individu & tim",q:"Kombinasi refleksi yang lengkap:",options:["Tiap anggota menilai kontribusinya sendiri + tim menilai proses kerjanya bersama","Hanya menilai tim, tidak diri sendiri","Hanya menilai diri sendiri, tidak tim"],answer:0,explain:"Refleksi diri menangkap 'apa yang bisa AKU ubah'; refleksi tim menangkap 'apa yang bisa KITA ubah'. Keduanya perlu.",hint:"Diri + tim, atau salah satu?"},
{n:25,type:"mcq",micro:"Menjaga refleksi tetap aman",q:"Bila saat refleksi seseorang mulai menyerang pribadi anggota lain, fasilitator sebaiknya...",options:["Ikut menyerang","Mengarahkan kembali: 'Ayo kita bahas prosesnya, bukan orangnya. Apa yang bisa kita ubah supaya ini nggak terjadi lagi?'","Membiarkan agar 'jujur'"],answer:1,explain:"Menjaga refleksi tetap tentang proses melindungi rasa aman & membuatnya tetap produktif.",hint:"Kembalikan ke proses, atau biarkan / ikut menyerang?"},
{n:26,type:"mcq",micro:"Refleksi & pujian spesifik",q:"Apresiasi dalam refleksi lebih bermakna bila...",options:["Umum & singkat","Tidak diberikan sama sekali","Spesifik: 'Cara Ana menyusun jadwal bikin kita nggak keteteran' — bukan sekadar 'kerja bagus semua'"],answer:2,explain:"Pujian spesifik mengajarkan tim perilaku apa yang berhasil & layak diulang.",hint:"Spesifik (perilaku yang berhasil), atau umum?"},
{n:27,type:"tf",micro:"Refleksi menghasilkan sedikit perubahan",q:"Benar atau Salah: Refleksi tim lebih efektif bila menghasilkan daftar panjang berisi 10 perbaikan, karena semakin banyak yang teridentifikasi semakin baik.",answer:false,explain:"Sebaliknya, fokus pada 1-2 perubahan penting yang benar-benar diterapkan membuat tim berubah. Daftar 10 perbaikan membuat tim kewalahan & akhirnya tidak melakukan apa-apa.",hint:"1-2 perubahan diterapkan, atau daftar panjang tak dikerjakan?"},
{n:28,type:"tf",micro:"Refleksi = curhat tanpa tindakan?",q:"Benar atau Salah: Sesi refleksi tim yang berisi banyak keluhan tetapi tidak menghasilkan satu pun rencana perubahan konkret sudah cukup berguna, karena semua jadi lega.",answer:false,explain:"Sebaliknya, refleksi tanpa tindakan hanya jadi sesi curhat. Yang membuat refleksi berharga adalah perubahan nyata yang diterapkan setelahnya.",hint:"Lega saja cukup, atau butuh rencana perubahan?"},
{n:29,type:"mcq",micro:"Refleksi & anggota yang defensif",q:"Seorang anggota selalu defensif setiap kritik proses disebut, seolah menyerang dia. Sikap tim:",options:["Tegaskan berulang bahwa ini soal proses tim, beri contoh yang tidak menunjuk orang, & modelkan menerima masukan diri sendiri lebih dulu","Berhenti membahas apa pun yang menyangkut dia","Menyerang dia balik"],answer:0,explain:"Kalau fasilitator/ketua sendiri terbuka pada kritik ('aku juga kurang mengingatkan tenggat'), anggota lain lebih mudah ikut.",hint:"Tegaskan fokus proses + modelkan menerima, atau berhenti / menyerang?"},
{n:30,type:"order",micro:"Dari refleksi ke perbaikan yang diterapkan",q:"Urutkan langkah agar hasil refleksi benar-benar diterapkan.",items:["Pilih 1-2 perubahan terpenting dari refleksi","Buat spesifik: apa persisnya yang berubah, siapa yang memastikan, mulai kapan","Tuliskan & bagikan ke semua anggota","Di awal proyek berikutnya, buka catatan itu; di refleksi tengah, cek apakah dijalankan"],answer:[0,1,2,3],explain:"Pilih prioritas → buat spesifik + penanggung jawab → tulis & bagikan → cek penerapan. Tanpa langkah 4, perubahan sering menguap.",hint:"Apa yang dilakukan agar perubahan tidak dilupakan?"},
{n:31,type:"mcq",micro:"Refleksi & kejujuran vs kesopanan",q:"Refleksi yang berguna butuh keseimbangan:",options:["Selalu jujur meski menyakiti pribadi","Jujur soal masalah nyata, DENGAN cara yang sopan & fokus proses — bukan menyembunyikan masalah demi sopan, bukan kasar demi jujur","Selalu sopan meski masalah besar disembunyikan"],answer:1,explain:"Refleksi yang terlalu 'sopan' melewatkan masalah penting; yang terlalu 'jujur kasar' melukai. Jujur + fokus proses.",hint:"Jujur + sopan + fokus proses, atau sembunyikan / kasar?"},
{n:32,type:"tf",micro:"Refleksi setelah proyek berhasil",q:"Benar atau Salah: Setelah proyek yang berhasil, refleksi tidak diperlukan karena tidak ada yang perlu diperbaiki.",answer:false,explain:"Sebaliknya, refleksi setelah sukses berguna untuk mengenali APA yang membuatnya berhasil (agar sengaja diulang) & apa yang tetap bisa lebih baik. Keberhasilan yang tak dipahami sebabnya sulit diulang.",hint:"Berguna setelah sukses juga, atau hanya setelah gagal?"},
{n:33,type:"mcq",micro:"Refleksi & perbedaan persepsi",q:"Saat refleksi, dua anggota punya versi berbeda tentang 'apa yang terjadi'. Sikap:",options:["Percaya yang lebih vokal","Abaikan perbedaan","Dengar kedua versi; sering perbedaan persepsi ITU SENDIRI adalah temuan penting (mis. komunikasi tidak jelas); cari fakta bila memungkinkan"],answer:2,explain:"Kalau dua anggota mengingat kejadian yang sama secara berbeda, itu sinyal ada yang perlu diperbaiki dalam cara tim berkomunikasi.",hint:"Perbedaan persepsi = temuan penting, atau abaikan / ikut yang vokal?"},
{n:34,type:"mcq",micro:"Refleksi & pemimpin",q:"Peran ketua/koordinator dalam refleksi tim:",options:["Memfasilitasi dengan jujur, termasuk mengakui kekurangannya sendiri sebagai pemimpin — bukan hanya mengevaluasi anggota","Menilai anggota & tidak menilai dirinya","Melewatkan refleksi karena 'sudah selesai'"],answer:0,explain:"Pemimpin yang berani mengakui 'aku kurang di sini' membuat refleksi terasa aman & tulus bagi semua.",hint:"Fasilitasi + akui kekurangan sendiri, atau hanya nilai anggota?"},
{n:35,type:"mcq",micro:"Refleksi cepat vs mendalam",q:"Untuk proyek kecil, refleksi bisa...",options:["Tidak perlu untuk proyek kecil","Singkat: 3 menit di akhir — 'apa yang oke? apa yang diubah lain kali?' Tidak harus sesi panjang","Selalu butuh 1 jam"],answer:1,explain:"Sesuaikan kedalaman refleksi dengan besarnya proyek. Bahkan refleksi 3 menit lebih baik daripada tidak sama sekali.",hint:"Singkat untuk proyek kecil, atau selalu panjang / tidak perlu?"},
{n:36,type:"mcq",micro:"Refleksi & pola berulang",q:"Kalau refleksi beberapa proyek menemukan MASALAH YANG SAMA terus muncul (mis. selalu telat), ini berarti...",options:["Tim ini memang ditakdirkan begitu","Refleksi tidak berguna","Perubahan yang disepakati sebelumnya tidak benar-benar diterapkan, atau akar masalahnya belum ketemu — gali lebih dalam & buat perubahan yang lebih kuat"],answer:2,explain:"Masalah yang berulang meski sudah direfleksikan = perubahan tidak dijalankan atau salah sasaran. Perlu evaluasi yang lebih serius.",hint:"Perubahan tak diterapkan / akar belum ketemu, atau tim ditakdirkan?"},
{n:37,type:"tf",micro:"Refleksi bisa dilatih",q:"Benar atau Salah: Kemampuan tim untuk merefleksikan diri dengan jujur & produktif — fokus proses, menyeimbangkan pujian & kritik, menghasilkan perubahan konkret — bisa membaik dengan latihan & pengulangan.",answer:true,explain:"Refleksi pertama sering canggung. Tim yang rutin melakukannya jadi lebih terbuka & lebih efektif dari waktu ke waktu.",hint:"Bisa membaik dengan latihan, atau tetap?"},
{n:38,type:"mcq",micro:"Refleksi & individu yang berkembang",q:"Anggota yang secara jujur menilai kontribusinya sendiri di tiap refleksi ('aku telat 2x, lain kali aku set pengingat') cenderung...",options:["Berkembang lebih cepat menjadi anggota tim yang andal","Terlihat lemah","Tidak berubah"],answer:0,explain:"Kesadaran diri yang jujur adalah langkah pertama perbaikan. Yang selalu menyalahkan orang lain tidak berkembang.",hint:"Berkembang lebih cepat, atau terlihat lemah?"},
{n:39,type:"mcq",micro:"Refleksi & apresiasi antar anggota",q:"Bagian refleksi di mana anggota saling menyebut kontribusi yang mereka hargai dari satu sama lain berfungsi...",options:["Membuat suasana canggung","Menguatkan hubungan & semangat tim, & membuat kontribusi 'di belakang layar' terlihat","Membuang waktu"],answer:1,explain:"Refleksi bukan hanya soal perbaikan — juga soal saling menghargai, yang menjaga tim tetap solid.",hint:"Menguatkan hubungan & semangat, atau buang waktu?"},
{n:40,type:"open",micro:"Menganalisis refleksi yang gagal",q:"Sebuah tim melakukan 'refleksi': ketua bilang 'proyek kita lumayan lah, ada yang mau komentar?', dua anggota menyebut Deni yang bagiannya selalu telat, Deni membela diri & suasana jadi tegang, ketua bilang 'ya sudah, yang penting selesai', lalu bubar. Jelaskan minimal 4 kesalahan dalam refleksi ini, lalu tulis bagaimana seharusnya.",sample:"Kesalahan: (1) Tidak ada aturan/tujuan jelas di awal ('fokus pada proses, bukan orang'), jadi refleksi langsung berubah jadi menyalahkan individu (Deni). (2) Pembukaan yang lemah ('ada yang mau komentar?') tidak mengundang refleksi terstruktur — hanya mengundang keluhan dari yang paling vokal. (3) Fokus pada 'siapa yang salah' (Deni telat) bukan pada 'kenapa sistem kita membiarkan keterlambatan tidak tertangani sampai akhir'. (4) Deni tidak diberi ruang menjelaskan kendalanya secara adil sebelum dihakimi; ketika ia membela diri, tidak ada yang mengarahkan diskusi kembali ke proses. (5) Ketua menutup dengan 'yang penting selesai' — tidak ada pelajaran yang diambil dan tidak ada perubahan konkret yang disepakati, jadi masalah yang sama pasti terulang. (6) Tidak ada bagian yang menyebut apa yang berjalan baik. Seharusnya: (a) Ketua membuka dengan tujuan & aturan: 'Kita review biar proyek berikutnya lebih lancar. Fokus ke cara kerja kita, bukan menyalahkan orang. Semua bicara bergiliran.' (b) Putar giliran: tiap orang menyebut satu hal yang berjalan baik + satu hal yang menghambat. (c) Ketika keterlambatan bagian tertentu muncul, arahkan ke proses: 'Kenapa keterlambatan itu baru ketahuan di akhir? Apa yang bisa membuat kita tahu lebih awal?' — mungkin jawabannya: tidak ada cek kemajuan rutin & tidak ada aturan wajib mengabari kendala. (d) Beri Deni (dan semua) ruang menjelaskan kendalanya tanpa dihakimi. (e) Sepakati 1-2 perubahan konkret: cek kemajuan tiap 3 hari + wajib mengabari kendala minimal 1 hari sebelum tenggat bagian. Tulis siapa yang memastikan & mulai kapan. (f) Tutup dengan mengapresiasi usaha semua.",explain:"Jawaban baik menyebut minimal 4 kesalahan (tanpa aturan/tujuan → menyalahkan individu, pembukaan lemah, fokus 'siapa salah' bukan proses, Deni tidak diberi ruang adil, tidak ada perubahan konkret / pelajaran, tidak menyebut yang berjalan baik) dan menulis proses yang benar: aturan fokus proses → giliran (baik + menghambat) → arahkan keterlambatan ke akar proses → ruang menjelaskan tanpa dihakimi → 1-2 perubahan konkret + penanggung jawab → apresiasi.",hint:"Cari: tanpa aturan (jadi menyalahkan orang), pembukaan lemah, fokus siapa-salah, Deni tak diberi ruang, tanpa perubahan konkret, tak ada yang berjalan baik disebut. Tulis: aturan proses → giliran → akar → ruang menjelaskan → perubahan konkret → apresiasi."},

// FASE C — PENERAPAN (41-60)
{n:41,type:"mcq",micro:"Skenario: refleksi tengah menemukan proyek menyimpang",q:"Refleksi di titik tengah menemukan hasil sejauh ini tidak sesuai tujuan proyek. Sikap tim:",options:["Lanjut saja karena 'sudah terlanjur'","Menyalahkan yang bagiannya paling menyimpang","Bahas: apa yang menyebabkan menyimpang? apa yang perlu diubah (rencana, pembagian, cara kerja) supaya kembali ke jalur? — lakukan penyesuaian selagi masih ada waktu"],answer:2,explain:"Refleksi tengah yang menemukan penyimpangan adalah kabar baik — masih ada waktu memperbaiki. Sesuaikan, jangan lanjut buta.",hint:"Sesuaikan selagi ada waktu, atau lanjut / menyalahkan?"},
{n:42,type:"mcq",micro:"Skenario: refleksi & kamu ikut andil masalah",q:"Saat refleksi, kamu sadar kebiasaanmu (mis. tidak mengabari kendala) ikut memicu masalah tim. Sikap:",options:["Akui terbuka: 'Aku sadar aku sering nggak kabari kalau bagianku telat, dan itu bikin tim kaget di akhir. Lain kali aku akan kabari lebih awal.'","Diam & berharap tidak ada yang menyebutnya","Menyalahkan orang lain untuk mengalihkan"],answer:0,explain:"Anggota yang berani mengakui andilnya membuat refleksi lebih jujur & mendorong yang lain melakukan hal sama.",hint:"Akui terbuka + niat perbaikan, atau diam / mengalihkan?"},
{n:43,type:"mcq",micro:"Skenario: refleksi untuk kegiatan berulang",q:"Untuk kegiatan rutin (mis. mengelola kantin sekolah tiap minggu), refleksi yang berguna:",options:["Tidak perlu refleksi untuk kegiatan rutin","Refleksi singkat rutin (mis. 5 menit tiap akhir minggu) untuk menangkap masalah kecil sebelum menumpuk + refleksi lebih dalam sebulan sekali","Hanya refleksi besar di akhir semester"],answer:1,explain:"Kegiatan berulang mendapat manfaat besar dari refleksi kecil yang sering — masalah kecil ditangkap & diperbaiki terus.",hint:"Singkat rutin + dalam berkala, atau hanya akhir semester / tidak sama sekali?"},
{n:44,type:"mcq",micro:"Skenario: refleksi menemukan konflik yang belum selesai",q:"Refleksi mengungkap bahwa dua anggota masih menyimpan kekesalan sejak konflik lama. Sikap fasilitator:",options:["Abaikan karena 'bukan topik refleksi'","Paksa mereka berbaikan sekarang di depan semua","Akui bahwa ini perlu ditangani; tawarkan sesi terpisah untuk membahas konflik itu dengan tenang — jangan mencoba menyelesaikan konflik pribadi mendalam di tengah refleksi kelompok"],answer:2,explain:"Refleksi bisa MENGUNGKAP masalah yang butuh penanganan terpisah. Akui & jadwalkan, jangan abaikan atau paksa di forum ramai.",hint:"Akui + tawarkan sesi terpisah, atau abaikan / paksa di depan semua?"},
{n:45,type:"order",micro:"Refleksi diri sebagai anggota tim",q:"Urutkan langkah merefleksikan kontribusimu sendiri setelah proyek.",items:["Tanya: apakah aku menepati bagianku sesuai standar & tenggat?","Tanya: apakah aku mengabari kendala tepat waktu & membantu anggota lain saat perlu?","Tanya: apakah aku mendengar & berkontribusi dalam keputusan, atau pasif/dominan?","Pilih satu hal spesifik yang akan kuperbaiki di proyek berikutnya"],answer:[0,1,2,3],explain:"Menepati bagian → komunikasi & bantuan → keterlibatan dalam keputusan → satu perbaikan spesifik. Refleksi diri yang jujur & terarah.",hint:"Apa yang ditanya pertama tentang bagianmu sendiri?"},
{n:46,type:"mcq",micro:"Skenario: refleksi & anggota yang menganggapnya buang waktu",q:"Seorang anggota bilang 'ngapain sih refleksi, proyek udah kelar'. Respons yang membujuk:",options:["'5 menit aja buat catat 1-2 hal yang bikin kita mepet, biar proyek berikutnya nggak gitu lagi. Ini justru bikin lebih gampang nanti.' — bingkai sebagai penghemat kesulitan","Menyerah & tidak refleksi","Memaksa dengan marah"],answer:0,explain:"Bingkai refleksi sebagai investasi kecil yang mencegah kesulitan besar berikutnya, & buat singkat.",hint:"Bingkai sebagai penghemat kesulitan + singkat, atau menyerah / memaksa?"},
{n:47,type:"mcq",micro:"Skenario: refleksi menghasilkan perubahan yang sulit",q:"Refleksi menyimpulkan tim butuh berubah cara kerja secara cukup besar (mis. dari 'kerjakan bareng semua' ke 'bagi peran jelas'). Sikap:",options:["Ubah total tanpa evaluasi","Sepakati untuk mencoba perubahan itu di proyek berikutnya sebagai eksperimen, lalu evaluasi apakah lebih baik — bukan langsung menolak karena 'tidak biasa'","Tetap dengan cara lama karena nyaman"],answer:1,explain:"Perubahan cara kerja lebih mudah diterima bila dibingkai sebagai 'coba dulu, evaluasi', bukan keputusan permanen.",hint:"Coba sebagai eksperimen + evaluasi, atau tolak / ubah buta?"},
{n:48,type:"mcq",micro:"Skenario: refleksi & guru/penilai",q:"Menyertakan hasil refleksi tim (apa yang dipelajari, apa yang akan diperbaiki) dalam laporan ke guru...",options:["Membuat tim terlihat buruk","Sebaiknya disembunyikan","Menunjukkan tim yang matang & mau belajar; sering dihargai lebih daripada tim yang berpura-pura semuanya sempurna"],answer:2,explain:"Kemampuan menilai diri sendiri secara jujur adalah tanda kedewasaan yang dihargai, bukan kelemahan.",hint:"Menunjukkan tim matang, atau membuat terlihat buruk?"},
{n:49,type:"mcq",micro:"Skenario: refleksi & anggota yang selalu menyalahkan orang lain",q:"Saat refleksi, seorang anggota hanya menyebut kesalahan orang lain, tidak pernah dirinya. Sikap fasilitator:",options:["Ajak semua (termasuk dia) menyebut satu hal yang bisa DIRINYA SENDIRI perbaiki; modelkan dengan menyebut kekuranganmu sendiri lebih dulu","Biarkan dia menyalahkan terus","Menyerang dia balik"],answer:0,explain:"Struktur 'tiap orang sebut satu perbaikan diri' + fasilitator yang mencontohkan membuat sulit bagi seseorang untuk hanya menyalahkan.",hint:"Ajak semua sebut perbaikan diri + modelkan, atau biarkan / menyerang?"},
{n:50,type:"open",micro:"Menjalankan refleksi tengah proyek",q:"Proyek timmu (5 orang) sudah berjalan 2 minggu dari 4 minggu. Kamu merasa ada yang kurang beres (beberapa bagian tersendat, komunikasi mulai jarang) tapi belum ada krisis. Rancang refleksi TENGAH proyek 15 menit: struktur, pertanyaan, dan hasil yang harus keluar — serta jelaskan mengapa refleksi tengah berbeda tujuannya dari refleksi akhir.",sample:"Struktur refleksi tengah 15 menit: (1) [1 menit] Buka dengan tujuan: 'Kita di titik tengah. Tujuan review ini bukan menilai hasil — belum ada hasil akhir — tapi mengecek apakah kita di jalur dan menyesuaikan selagi masih ada 2 minggu.' Aturan: fokus proses, semua bicara. (2) [5 menit] Cek jalur, bergiliran: tiap anggota menjawab — 'Bagianmu sejauh mana dibanding rencana?' dan 'Ada kendala yang menghambatmu sekarang?'. Catat. (3) [3 menit] Cek cara kerja tim: 'Apa yang mulai kurang lancar di cara kita bekerja bersama?' (mis. komunikasi jarang, tidak ada cek kemajuan). (4) [4 menit] Sepakati penyesuaian konkret untuk 2 minggu sisa: mis. 'cek kemajuan tiap 3 hari lewat chat', 'yang bagiannya tersendat dibantu anggota yang sudah selesai', 'geser sub-tugas X dari [nama] ke [nama]'. Tulis: penyesuaian apa, siapa, mulai kapan. (5) [2 menit] Sepakati kapan kita cek lagi apakah penyesuaian ini membantu (mis. minggu depan). Hasil yang harus keluar: gambaran jelas posisi tiap bagian vs rencana + daftar kendala + 1-3 penyesuaian konkret untuk sisa waktu + jadwal cek berikutnya. Mengapa berbeda dari refleksi akhir: refleksi TENGAH bertujuan MENYESUAIKAN & menyelamatkan proyek yang sedang berjalan selagi masih ada waktu — fokusnya ke depan (2 minggu sisa) dan tindakannya segera diterapkan pada proyek ini. Refleksi AKHIR bertujuan BELAJAR untuk proyek berikutnya — fokusnya menarik pelajaran dari keseluruhan yang sudah selesai. Refleksi tengah lebih tentang 'apa yang kita ubah SEKARANG', refleksi akhir lebih tentang 'apa yang kita bawa ke LAIN KALI'.",explain:"Jawaban baik: struktur berjangka waktu (buka tujuan+aturan → cek jalur bergiliran (posisi vs rencana + kendala) → cek cara kerja tim → penyesuaian konkret untuk sisa waktu + siapa + kapan → jadwal cek berikutnya), hasil yang harus keluar (posisi tiap bagian, kendala, 1-3 penyesuaian, jadwal cek), dan menjelaskan bedanya dari refleksi akhir: refleksi tengah untuk MENYESUAIKAN proyek yang berjalan (fokus ke depan, tindakan segera), refleksi akhir untuk BELAJAR bagi proyek berikutnya.",hint:"Struktur: buka tujuan (mengecek jalur, bukan menilai hasil) → cek posisi tiap bagian + kendala bergiliran → cek cara kerja tim → penyesuaian konkret untuk sisa waktu + siapa + kapan → jadwal cek lagi. Jelaskan: tengah = menyesuaikan proyek ini; akhir = belajar untuk lain kali."},
{n:51,type:"mcq",micro:"Skenario: refleksi & anggota yang membandingkan dengan tim lain",q:"Saat refleksi, seorang anggota terus berkata 'tim sebelah lebih bagus dari kita'. Sikap yang produktif:",options:["Larang membandingkan sama sekali","Arahkan ke yang bisa kita kendalikan: 'Oke, apa spesifiknya yang mereka lakukan lebih baik & bisa kita adopsi?' — jadikan pembanding sebagai sumber ide, bukan hanya keluhan","Setuju & berkecil hati"],answer:1,explain:"Membandingkan bisa berguna bila diubah jadi 'apa yang bisa kita pelajari & tiru', bukan sekadar merendahkan tim sendiri.",hint:"Ubah jadi ide yang bisa diadopsi, atau berkecil hati / larang?"},
{n:52,type:"mcq",micro:"Skenario: refleksi menemukan komunikasi yang buruk",q:"Refleksi mengungkap banyak masalah berakar dari 'info penting hanya diketahui sebagian orang'. Perubahan konkret yang tepat:",options:["'Semua harus lebih komunikatif' (kabur)","Tidak mengubah apa-apa","Sepakati satu kanal utama untuk semua info proyek + aturan bahwa keputusan & info penting wajib ditulis di situ + yang tidak hadir rapat wajib membaca notulen"],answer:2,explain:"Perubahan yang berguna itu spesifik & bisa dijalankan ('satu kanal + wajib tulis'), bukan sikap kabur ('lebih komunikatif').",hint:"Aturan kanal & pencatatan yang spesifik, atau 'lebih komunikatif' / diam?"},
{n:53,type:"mcq",micro:"Skenario: refleksi tim yang jarang bertemu (online)",q:"Timmu bekerja sepenuhnya online & jarang bisa rapat. Cara melakukan refleksi:",options:["Refleksi tertulis: tiap anggota mengisi 3 pertanyaan (baik/menghambat/usul perubahan) di dokumen bersama, lalu satu pertemuan singkat online untuk menyepakati 1-2 perubahan","Lewatkan refleksi karena sulit dijadwalkan","Ketua merefleksikan sendiri untuk semua"],answer:0,explain:"Refleksi tidak harus tatap muka. Format tertulis + pertemuan singkat penyimpul bekerja untuk tim online.",hint:"Tertulis + pertemuan singkat penyimpul, atau lewatkan / ketua sendiri?"},
{n:54,type:"mcq",micro:"Skenario: refleksi menghasilkan pujian untuk anggota tertentu",q:"Dalam refleksi, jelas satu anggota (mis. yang selalu menyiapkan data tepat waktu) berkontribusi sangat besar. Sikap:",options:["Beri semua pujian ke yang presentasi saja","Akui secara terbuka & spesifik: 'Data yang [nama] siapkan tiap minggu bikin kita nggak pernah keteteran — itu besar banget.' — pengakuan menguatkan perilaku baik & semangatnya","Anggap biasa karena 'itu memang tugasnya'"],answer:1,explain:"Refleksi juga tempat mengakui kontribusi yang mungkin luput dari sorotan. Pengakuan spesifik membuat orang mau memberi yang terbaik lagi.",hint:"Akui spesifik & terbuka, atau anggap biasa / salah sasaran?"},
{n:55,type:"mcq",micro:"Skenario: refleksi & keputusan yang ternyata bagus",q:"Refleksi meninjau sebuah keputusan sulit yang tim ambil di tengah proyek & ternyata tepat. Yang berguna dibahas:",options:["Cukup senang bahwa hasilnya bagus","Keputusan yang berhasil tidak perlu dibahas","Apa yang membuat proses keputusan itu baik (info cukup? semua didengar? kriteria jelas?) supaya bisa diulang di keputusan berikutnya"],answer:2,explain:"Memahami MENGAPA sebuah keputusan berjalan baik (bukan hanya bahwa hasilnya bagus) membantu tim mengulang proses yang baik.",hint:"Bahas apa yang bikin prosesnya baik, atau cukup senang?"},
{n:56,type:"mcq",micro:"Skenario: refleksi & anggota yang tidak setuju hasil evaluasi",q:"Setelah refleksi menyimpulkan sesuatu, seorang anggota merasa kesimpulan itu tidak adil/tidak akurat. Sikap:",options:["Beri ia ruang menjelaskan pandangannya & data pendukungnya; kesimpulan refleksi bisa disesuaikan bila ia menunjukkan hal yang terlewat — refleksi bukan vonis","Abaikan karena 'mayoritas sudah setuju'","Batalkan seluruh refleksi"],answer:0,explain:"Refleksi adalah proses mencari pemahaman, bukan pemungutan suara. Pandangan yang beralasan layak mengubah kesimpulan.",hint:"Beri ruang + sesuaikan bila terlewat, atau abaikan / batalkan?"},
{n:57,type:"mcq",micro:"Skenario: refleksi & tim yang baru terbentuk",q:"Timmu baru dibentuk & belum pernah bekerja bersama. Refleksi awal yang berguna:",options:["Tidak perlu, tim baru belum punya apa-apa untuk direfleksikan","Setelah tugas kecil pertama, refleksi singkat: 'Gimana rasanya kerja bareng sejauh ini? Apa yang perlu kita sepakati/perjelas supaya lebih lancar?' — membangun kebiasaan sejak awal","Tunggu sampai proyek besar selesai"],answer:1,explain:"Refleksi setelah tugas kecil pertama membantu tim baru menyesuaikan diri sebelum masuk proyek besar & menormalkan kebiasaan refleksi.",hint:"Refleksi singkat setelah tugas kecil pertama, atau tunggu proyek besar?"},
{n:58,type:"tf",micro:"Refleksi diri sebelum refleksi tim",q:"Benar atau Salah: Meminta anggota merefleksikan kontribusinya sendiri sebelum refleksi tim justru membuat sesi bersama lebih defensif & tidak produktif.",answer:false,explain:"Sebaliknya, refleksi diri dulu membuat sesi bersama lebih jujur, karena tiap orang sudah menghadapi 'apa yang bisa AKU perbaiki' & tidak sekadar menyalahkan orang lain di forum.",hint:"Refleksi diri dulu membantu, atau membuat defensif?"},
{n:59,type:"open",micro:"Menyusun format refleksi singkat",q:"Buat 'format refleksi tim 10 menit' yang bisa dipakai berulang setelah tiap proyek kecil: tuliskan langkah-langkahnya, pertanyaan yang ditanyakan, dan hasil yang harus keluar dari sesi itu. Jelaskan mengapa formatmu efektif meski singkat.",sample:"Format refleksi tim 10 menit: (1) [1 menit] Fasilitator menyebut aturan: 'Fokus ke proses & perbaikan, bukan menyalahkan orang. Semua bicara. Kita akhiri dengan 1 perubahan.' (2) [4 menit] Putar giliran: tiap anggota menjawab dua pertanyaan singkat — 'Satu hal yang berjalan baik dan kita harus pertahankan?' dan 'Satu hal yang paling menghambat kita?'. Fasilitator mencatat semua jawaban di satu tempat yang terlihat. (3) [2 menit] Fasilitator membacakan poin-poin, mengelompokkan yang mirip, dan tim memilih SATU masalah paling penting untuk diperbaiki. (4) [2 menit] Tim menyepakati satu perubahan konkret untuk mengatasi masalah itu: apa persisnya yang berubah, siapa yang memastikan, mulai kapan. Ditulis. (5) [1 menit] Fasilitator menutup dengan menyebut satu kontribusi spesifik dari tiap anggota yang dihargai. Hasil yang harus keluar: catatan tertulis berisi (a) 1-2 hal yang berjalan baik (untuk dipertahankan), (b) satu perubahan konkret + penanggung jawab + kapan mulai. Mengapa efektif meski singkat: (i) giliran memastikan semua didengar, bukan hanya yang vokal; (ii) membatasi ke SATU perubahan mencegah tim kewalahan & memastikan perubahan itu benar-benar dijalankan; (iii) aturan 'fokus proses' di awal mencegah sesi berubah jadi menyalahkan; (iv) penutup apresiasi menjaga refleksi terasa membangun sehingga tim mau melakukannya lagi; (v) catatan tertulis membuat pelajaran tidak menguap & bisa dicek di proyek berikutnya.",explain:"Jawaban baik menghasilkan format berjangka waktu dengan langkah jelas (aturan → giliran menjawab 2 pertanyaan → kelompokkan & pilih 1 masalah → 1 perubahan konkret + penanggung jawab + kapan → penutup apresiasi), menyebut hasil yang harus keluar (catatan: hal yang dipertahankan + 1 perubahan konkret bertanggung jawab), dan menjelaskan kenapa efektif meski singkat (giliran = semua didengar, batasi 1 perubahan = tidak kewalahan & benar dijalankan, aturan fokus proses, apresiasi menjaga berkelanjutan, catatan mencegah menguap).",hint:"Format: aturan → giliran (baik + menghambat) → pilih 1 masalah → 1 perubahan konkret + siapa + kapan → apresiasi. Hasil: catatan (pertahankan + 1 perubahan). Jelaskan kenapa singkat tetap efektif."},
{n:60,type:"open",micro:"Skenario menyeluruh",q:"Kamu ketua tim OSIS. Setahun kepengurusan hampir selesai. Kamu ingin melakukan refleksi menyeluruh: apa yang dicapai, apa yang kurang, & pelajaran untuk kepengurusan berikutnya — dan memastikan pelajarannya benar-benar diwariskan. Rancang bagaimana kamu menjalankan ini (minimal 6 langkah).",sample:"(1) Siapkan bahan sebelumnya: kumpulkan fakta setahun — program yang terlaksana/tidak, kehadiran rapat, umpan balik siswa/guru, masalah yang berulang. Bagikan ringkasannya ke anggota sebelum sesi supaya mereka bisa memikirkannya. (2) Buka sesi dengan tujuan & aturan: 'Kita review setahun ini bukan buat cari salah, tapi biar kepengurusan berikutnya lebih baik. Fokus ke proses & pelajaran. Semua bicara.' (3) Refleksi TIM (bergiliran): tiap anggota menyebut satu pencapaian yang paling dibanggakan (+ kenapa berhasil) & satu hal yang paling menghambat (+ kenapa). Catat di tempat yang terlihat. (4) Refleksi PER BIDANG: tiap penanggung jawab bidang menyampaikan singkat apa yang berjalan, apa yang tidak, & satu saran konkret untuk penerusnya. (5) Kelompokkan temuan & pilih 3-5 PELAJARAN UTAMA (mis. 'program butuh tenggat & penanggung jawab tertulis sejak awal', 'komunikasi antar bidang perlu forum rutin', 'anggaran perlu dicatat transparan sejak hari pertama'). (6) Ubah tiap pelajaran jadi REKOMENDASI KONKRET berbentuk tindakan untuk pengurus berikutnya ('buat template rencana program di minggu pertama', dst.), bukan keluhan abstrak. (7) Susun DOKUMEN SERAH TERIMA: ringkasan pencapaian, pelajaran utama + rekomendasi konkret, kontak untuk bertanya, & 'jebakan yang harus dihindari'. (8) Adakan pertemuan singkat dengan pengurus baru untuk menyerahkan dokumen & menjelaskan langsung — bukan sekadar mengirim file — dan sarankan mereka membukanya saat menyusun program pertama. (9) Tutup dengan apresiasi: sebut kontribusi tiap anggota secara spesifik & rayakan apa yang berhasil.",explain:"Jawaban baik: siapkan fakta setahun + bagikan, buka dengan tujuan & aturan (fokus proses), refleksi tim bergiliran (pencapaian + hambatan + kenapa), refleksi per bidang + saran untuk penerus, kelompokkan & pilih pelajaran utama, ubah jadi rekomendasi konkret berbentuk tindakan, susun dokumen serah terima (pencapaian + pelajaran + rekomendasi + kontak + jebakan), pertemuan penjelasan langsung ke pengurus baru + saran kapan membukanya, tutup dengan apresiasi spesifik.",hint:"Siapkan fakta + bagikan → tujuan/aturan → refleksi tim bergiliran + per bidang → pilih pelajaran utama → ubah jadi rekomendasi tindakan → dokumen serah terima + pertemuan penjelasan langsung → apresiasi."},

// FASE D — PENALARAN (61-80)
{n:61,type:"mcq",micro:"Mengapa refleksi rutin mengungguli refleksi sekali",q:"Mengapa tim yang refleksi rutin (tengah + akhir tiap proyek) berkembang lebih cepat daripada yang refleksi sesekali saja?",options:["Karena refleksi rutin membuat tim lelah","Tidak ada bedanya","Masalah ditangkap & diperbaiki lebih sering & lebih kecil; pelajaran diterapkan berkali-kali; kebiasaan baik menguat"],answer:2,explain:"Refleksi adalah putaran umpan balik. Semakin sering putarannya, semakin cepat tim menyesuaikan diri.",hint:"Putaran umpan balik lebih sering, atau membuat lelah?"},
{n:62,type:"mcq",micro:"Mengapa fokus proses bukan orang",q:"Mengapa refleksi yang fokus pada proses ('sistem kita kurang X') lebih efektif daripada yang fokus pada orang ('si A yang salah')?",options:["Fokus orang membuat orang defensif & menyembunyikan masalah lain kali; fokus proses menghasilkan perbaikan yang bisa dikerjakan tim & aman untuk semua","Fokus orang lebih jujur","Tidak ada bedanya"],answer:0,explain:"Bahkan bila satu orang benar-benar berandil, sering ada kegagalan proses (tidak ada cek, tidak ada aturan kabar) yang lebih berguna diperbaiki.",hint:"Fokus proses aman & bisa dikerjakan, atau fokus orang lebih jujur?"},
{n:63,type:"tf",micro:"Keberhasilan pun punya pelajaran",q:"Benar atau Salah: Proyek yang berhasil bisa saja berhasil karena keberuntungan atau kerja keras beberapa orang menutupi kelemahan proses — sehingga refleksi tetap berguna untuk mengetahui apakah keberhasilan itu berkelanjutan.",answer:true,explain:"'Berhasil kali ini' tidak berarti 'proses kita bagus'. Refleksi jujur setelah sukses memeriksa apakah tim benar-benar kuat atau hanya beruntung.",hint:"Sukses selalu berarti proses bagus, atau bisa karena keberuntungan?"},
{n:64,type:"mcq",micro:"Menilai kualitas refleksi",q:"Tanda sebuah refleksi tim berjalan baik:",options:["Berakhir dengan daftar panjang keluhan tanpa rencana","Semua ikut bicara, fokus tetap pada proses, ada 1-2 perubahan konkret yang disepakati, & anggota keluar merasa didengar bukan diserang","Hanya ketua bicara & menilai anggota"],answer:1,explain:"Refleksi yang baik = semua terlibat + fokus proses + menghasilkan aksi + menjaga rasa aman.",hint:"Semua terlibat + proses + aksi + aman, atau ketua menilai / keluhan tanpa rencana?"},
{n:65,type:"mcq",micro:"Refleksi & bias ingatan",q:"Mengapa berguna melihat catatan/fakta selama proyek saat refleksi, bukan hanya mengandalkan ingatan?",options:["Fakta tidak pernah membantu","Ingatan selalu akurat","Ingatan cenderung bias: kejadian terakhir terasa paling menonjol, & tiap orang mengingat dari sudut pandangnya; fakta menyeimbangkan itu"],answer:2,explain:"'Recency bias' & sudut pandang pribadi membuat refleksi tanpa data sering menyimpang. Catatan kecil selama proyek sangat membantu.",hint:"Ingatan bias, atau selalu akurat?"},
{n:66,type:"tf",micro:"Refleksi harus menghasilkan banyak perubahan?",q:"Benar atau Salah: Refleksi tim dianggap gagal bila hanya menghasilkan satu atau dua perubahan; refleksi yang baik harus menghasilkan daftar panjang perbaikan.",answer:false,explain:"Sebaliknya, 1-2 perubahan yang benar-benar diterapkan jauh lebih berharga daripada daftar 10 perbaikan yang membuat tim kewalahan & akhirnya tidak dilakukan.",hint:"Daftar panjang, atau 1-2 yang diterapkan?"},
{n:67,type:"mcq",micro:"Refleksi & kepemimpinan yang jujur",q:"Ketika seorang pemimpin tim membuka refleksi dengan mengakui kekurangannya sendiri ('aku kurang mengingatkan tenggat'), efeknya:",options:["Anggota merasa lebih aman mengakui kekurangan mereka juga; refleksi jadi lebih jujur & produktif","Pemimpin jadi tidak dihormati","Anggota jadi memanfaatkannya"],answer:0,explain:"Kerentanan pemimpin yang tulus menular positif — ia memberi 'izin' bagi semua untuk jujur.",hint:"Anggota lebih aman jujur, atau pemimpin tak dihormati?"},
{n:68,type:"mcq",micro:"Refleksi individu & tim saling melengkapi",q:"Mengapa refleksi diri (per anggota) & refleksi tim (bersama) keduanya penting?",options:["Keduanya membuang waktu","Refleksi diri menangkap 'apa yang bisa AKU ubah' yang mungkin tidak nyaman disebut orang lain di forum; refleksi tim menangkap 'apa yang bisa KITA ubah' di tingkat sistem","Cukup salah satu"],answer:1,explain:"Sebagian perbaikan bersifat pribadi (kebiasaanku), sebagian bersifat sistem (proses kita). Butuh dua jenis refleksi.",hint:"Menangkap dua tingkat berbeda, atau cukup satu?"},
{n:69,type:"mcq",micro:"Refleksi & pola yang berulang",q:"Bila masalah yang sama muncul di refleksi 3 proyek berturut-turut meski sudah 'dibahas', kemungkinan penyebabnya:",options:["Refleksi tidak berguna","Tim ini memang tidak bisa berubah","Perubahan yang disepakati tidak pernah benar-benar dijalankan, atau tim memperbaiki gejala bukan akar, atau tidak ada yang bertanggung jawab memastikan perubahan diterapkan"],answer:2,explain:"Pola berulang menunjukkan kesenjangan antara 'menyepakati perubahan' & 'menerapkannya'. Perlu penanggung jawab & pengecekan.",hint:"Perubahan tak diterapkan / gejala bukan akar / tanpa penanggung jawab, atau refleksi tak berguna?"},
{n:70,type:"order",micro:"Menutup lingkaran refleksi",q:"Urutkan siklus lengkap refleksi yang 'menutup lingkaran'.",items:["Refleksi menghasilkan 1-2 perubahan konkret + penanggung jawab + kapan mulai","Perubahan ditulis & dibagikan ke semua","Di awal proyek berikutnya, catatan dibuka sebagai pengingat & perubahan diterapkan","Di refleksi berikutnya, tim mengecek: apakah perubahan dijalankan? apakah membantu?"],answer:[0,1,2,3],explain:"Sepakati perubahan → tulis & bagikan → terapkan di proyek berikutnya → cek di refleksi berikutnya. Tanpa langkah terakhir, lingkaran tidak tertutup.",hint:"Apa langkah terakhir yang menutup lingkaran?"},
{n:71,type:"mcq",micro:"Refleksi & budaya tim",q:"Tim yang menjadikan refleksi kebiasaan normal (bukan hanya saat krisis) cenderung membangun budaya di mana...",options:["Masalah dibicarakan lebih awal & terbuka, kesalahan dilihat sebagai pelajaran, & tim terus membaik","Semua takut membuat kesalahan","Refleksi jadi formalitas kosong"],answer:0,explain:"Refleksi rutin menormalkan 'kita selalu bisa lebih baik' — sikap yang menjaga tim tumbuh.",hint:"Masalah dibahas dini + kesalahan jadi pelajaran, atau semua takut?"},
{n:72,type:"tf",micro:"Refleksi menghubungkan pengalaman ke perbaikan",q:"Benar atau Salah: Tanpa refleksi, pengalaman (bahkan pengalaman buruk) tidak otomatis berubah menjadi pelajaran — tim bisa mengulang kesalahan yang sama berkali-kali tanpa menyadari polanya.",answer:true,explain:"'Pengalaman adalah guru terbaik' hanya benar bila kamu merefleksikannya. Tanpa itu, pengalaman hanya jadi kejadian yang berulang.",hint:"Pengalaman otomatis jadi pelajaran, atau butuh refleksi?"},
{n:73,type:"mcq",micro:"Refleksi & waktu yang tepat",q:"Kapan sebaiknya refleksi akhir proyek dilakukan?",options:["Tepat di menit terakhir saat semua lelah & ingin pulang","Cukup dekat dengan selesainya proyek (saat ingatan masih segar) tapi tidak di saat semua kelelahan total — mungkin sehari-dua hari setelah, saat sudah tenang","Berbulan-bulan kemudian"],answer:1,explain:"Terlalu cepat = semua masih lelah/emosi; terlalu lambat = detail terlupa. Beberapa hari setelah sering pas.",hint:"Dekat tapi setelah tenang, atau berbulan / saat lelah?"},
{n:74,type:"mcq",micro:"Refleksi & anggota yang keluar/pindah tim",q:"Ketika seorang anggota akan meninggalkan tim, refleksi singkat dengannya berguna untuk...",options:["Tidak perlu, dia sudah mau pergi","Menyalahkannya atas semua masalah tim","Menangkap pandangan & pelajarannya sebelum hilang, & memastikan serah terima bagiannya lancar"],answer:2,explain:"Anggota yang pergi sering punya perspektif jujur (tidak lagi khawatir) & pengetahuan yang perlu ditangkap.",hint:"Tangkap pandangan & serah terima, atau abaikan / menyalahkan?"},
{n:75,type:"tf",micro:"Refleksi bukan mencari kesempurnaan",q:"Benar atau Salah: Tujuan refleksi tim adalah membuat proyek berikutnya sempurna & bebas masalah; bila masih ada masalah di proyek berikutnya, berarti refleksinya gagal.",answer:false,explain:"Sebaliknya, tujuan refleksi adalah membuat proyek berikutnya SEDIKIT lebih baik — perbaikan bertahap. Menuntut kesempurnaan membuat tim menyerah; perbaikan kecil yang konsisten berdampak besar seiring waktu.",hint:"Perbaikan bertahap, atau kesempurnaan?"},
{n:76,type:"mcq",micro:"Refleksi & keputusan yang diambil",q:"Refleksi juga berguna untuk meninjau KEPUTUSAN yang tim ambil selama proyek:",options:["Apakah prosesnya adil & matang? apakah kita punya info cukup? bagaimana kita bisa memutuskan lebih baik lain kali? — bukan sekadar 'keputusannya benar/salah'","Cukup menilai apakah hasilnya bagus","Keputusan tidak perlu direfleksikan"],answer:0,explain:"Menilai PROSES keputusan (bukan hanya hasil yang bisa dipengaruhi nasib) membuat tim memutuskan lebih baik ke depan.",hint:"Nilai proses keputusan, atau cukup hasil?"},
{n:77,type:"mcq",micro:"Refleksi & apresiasi menjaga keseimbangan",q:"Mengapa penting menyertakan apresiasi (bukan hanya kritik) dalam refleksi?",options:["Apresiasi tidak penting dalam refleksi","Menjaga semangat tim, membuat kontribusi 'tak terlihat' diakui, & mencegah refleksi terasa seperti hukuman yang membuat orang menghindarinya","Agar semua senang & tidak ada yang perlu diperbaiki"],answer:1,explain:"Refleksi yang hanya berisi kritik membuat orang takut & menghindari refleksi berikutnya. Apresiasi menjaganya sebagai kebiasaan yang berkelanjutan.",hint:"Menjaga semangat + kontribusi diakui + tidak seperti hukuman, atau tidak penting?"},
{n:78,type:"mcq",micro:"Refleksi & tanggung jawab menerapkan",q:"Agar hasil refleksi benar-benar diterapkan (bukan menguap), yang paling membantu:",options:["Berharap semua ingat","Menulis daftar panjang tanpa penanggung jawab","Menunjuk penanggung jawab spesifik untuk tiap perubahan + menetapkan kapan tim akan mengecek apakah dijalankan"],answer:2,explain:"Perubahan yang 'menjadi tanggung jawab semua orang' sering menjadi tanggung jawab tidak seorang pun. Tunjuk pemilik + jadwal cek.",hint:"Penanggung jawab + jadwal cek, atau berharap ingat?"},
{n:79,type:"mcq",micro:"Menilai apakah tim butuh refleksi lebih dalam",q:"Tanda tim butuh refleksi yang lebih serius/mendalam (bukan sekadar 5 menit):",options:["Masalah yang sama berulang, konflik yang belum selesai, hasil yang jauh di bawah harapan, atau anggota yang menarik diri/tidak terlibat","Semua berjalan lancar & anggota terlibat","Proyek kecil yang selesai baik"],answer:0,explain:"Gejala-gejala itu menandakan masalah yang lebih dalam dari sekadar 'perbaikan proses kecil'. Beri waktu & perhatian lebih.",hint:"Masalah berulang / konflik / hasil buruk / anggota menarik diri, atau semua lancar?"},
{n:80,type:"open",micro:"Membandingkan dua tim",q:"Tim A: tidak pernah refleksi ('proyek selesai ya sudah'), mengulang kesalahan yang sama (selalu mepet, beban tidak adil) di setiap proyek. Tim B: refleksi 15 menit di tengah & di akhir tiap proyek, fokus proses, menghasilkan 1-2 perubahan konkret yang diterapkan & dicek. Jelaskan mengapa Tim B akan jauh lebih efektif setelah beberapa proyek (minimal 4 alasan), dan 1 kesalahan yang bisa membuat refleksi Tim B tidak berguna.",sample:"Tim B akan jauh lebih efektif setelah beberapa proyek karena: (1) Setiap kesalahan menjadi pelajaran yang diterapkan, bukan diulang — jadi masalah seperti 'selalu mepet' atau 'beban tidak adil' diperbaiki lewat perubahan konkret (tenggat internal, cek kemajuan, perkiraan beban bersama), sementara Tim A terus mengalami masalah yang sama. (2) Refleksi tengah proyek memungkinkan Tim B menyesuaikan diri selagi masih ada waktu, jadi hasil tiap proyek juga lebih baik, bukan hanya proyek berikutnya. (3) Kebiasaan refleksi membangun budaya di mana masalah dibicarakan lebih awal dan terbuka, sehingga masalah kecil tidak menumpuk jadi besar. (4) Anggota Tim B saling lebih memahami cara kerja masing-masing dari waktu ke waktu, dan keterampilan mereka berefleksi & bekerja sama juga membaik — efek majemuk. (5) Karena perubahan dicek di refleksi berikutnya, Tim B tahu mana perbaikan yang berhasil dan mana yang perlu disesuaikan lagi. Kesalahan yang bisa membuat refleksi Tim B tidak berguna: bila refleksi menghasilkan kesepakatan perubahan tetapi tidak ada penanggung jawab yang memastikannya diterapkan, dan tidak ada pengecekan di refleksi berikutnya — sehingga 'lingkaran tidak tertutup' dan perubahan hanya jadi obrolan yang menguap. Kesalahan lain: bila refleksi berubah jadi sesi menyalahkan orang, anggota jadi defensif dan menyembunyikan masalah di lain waktu.",explain:"Jawaban baik memberi minimal 4 alasan Tim B lebih efektif (kesalahan jadi pelajaran yang diterapkan bukan diulang, refleksi tengah menyelamatkan proyek berjalan, budaya membicarakan masalah dini, anggota & keterampilan tim membaik / efek majemuk, perubahan dicek & disesuaikan) dan 1 kesalahan yang merusak refleksi (perubahan tanpa penanggung jawab & tanpa pengecekan = lingkaran tak tertutup / menguap; ATAU refleksi jadi sesi menyalahkan → defensif & menyembunyikan).",hint:"Alasan B: kesalahan jadi pelajaran diterapkan, refleksi tengah menyelamatkan, budaya bahas dini, tim & keterampilan membaik, perubahan dicek. Kesalahan: perubahan tanpa penanggung jawab/pengecekan, atau jadi sesi menyalahkan."},

// FASE E — TANTANGAN (81-100)
{n:81,type:"mcq",micro:"Kasus: refleksi setelah kegagalan besar",q:"Sebuah proyek/acara tim gagal cukup parah & semua kecewa. Cara menjalankan refleksi yang tetap membangun:",options:["Tidak refleksi sama sekali karena 'terlalu menyakitkan'","Beri waktu emosi mereda sedikit; buka dengan 'ini gagal & itu menyakitkan, tapi kita di sini buat belajar, bukan menyalahkan'; fokus pada apa yang bisa dipelajari & diperbaiki, akui andil masing-masing tanpa kambing hitam","Langsung refleksi saat semua masih marah & saling menyalahkan"],answer:1,explain:"Kegagalan besar butuh refleksi TERUTAMA — tapi setelah emosi sedikit reda, dengan aturan yang melindungi dari sesi menyalahkan.",hint:"Beri waktu + aturan anti-menyalahkan + fokus belajar, atau saat marah / tidak sama sekali?"},
{n:82,type:"mcq",micro:"Kasus: refleksi mengungkap ketua yang berandil besar dalam masalah",q:"Refleksi menunjukkan bahwa keputusan buruk ketua ikut menyebabkan masalah. Sikap tim & ketua:",options:["Tim menutupi kesalahan ketua demi 'menjaga wibawa'","Tim menyerang ketua habis-habisan","Ketua mengakuinya terbuka & tenang ('keputusanku soal X kurang tepat, aku belajar dari itu'); tim membahasnya sebagai proses (bagaimana kita bisa mengambil keputusan lebih baik bersama) bukan menjatuhkan ketua"],answer:2,explain:"Ketua yang mengakui kesalahannya dengan tenang memperkuat kepercayaan tim. Menutupi menyembunyikan pelajaran; menyerang merusak tim.",hint:"Ketua akui + bahas sebagai proses, atau tutupi / serang habis?"},
{n:83,type:"tf",micro:"Refleksi & evaluasi adalah keterampilan tim inti",q:"Benar atau Salah: Kemampuan sebuah tim untuk secara rutin & jujur meninjau cara kerjanya, belajar dari pengalaman, & menerapkan perbaikan adalah salah satu penentu terbesar apakah tim itu terus membaik atau stagnan.",answer:true,explain:"Tim berbakat yang tidak pernah refleksi bisa kalah dari tim biasa yang terus belajar & menyesuaikan diri.",hint:"Penentu tim membaik/stagnan, atau tidak penting?"},
{n:84,type:"mcq",micro:"Kasus: refleksi yang selalu menghasilkan hal yang sama",q:"Tiga refleksi terakhir menghasilkan perubahan yang sama ('buat tenggat internal') tapi tidak pernah dijalankan. Sikap:",options:["Bahas terus terang: kenapa perubahan ini tidak pernah jalan? Apakah tidak realistis? Tidak ada yang bertanggung jawab? Perlu bentuk yang berbeda? — perbaiki mekanisme penerapannya, bukan hanya menyepakati lagi","Sepakati lagi & berharap kali ini jalan","Menyerah pada refleksi"],answer:0,explain:"Bila perubahan yang sama terus disepakati tapi tak jalan, masalahnya di PENERAPAN, bukan di ide perubahannya. Perbaiki itu.",hint:"Bahas kenapa tak pernah jalan + perbaiki penerapan, atau sepakati lagi / menyerah?"},
{n:85,type:"order",micro:"Menjalankan refleksi tim untuk kegiatan berdurasi lama",q:"Urutkan pola refleksi untuk organisasi yang berjalan setahun.",items:["Refleksi singkat rutin (mis. akhir tiap kegiatan/bulan): tangkap masalah kecil & perbaiki cepat","Refleksi tengah periode (mis. setelah 6 bulan): tinjau apakah arah & cara kerja masih tepat, sesuaikan","Refleksi akhir periode: kumpulkan pencapaian & pelajaran utama","Serah terima: ubah pelajaran jadi rekomendasi konkret & wariskan ke pengurus berikutnya"],answer:[0,1,2,3],explain:"Rutin kecil → tengah (arah) → akhir (pelajaran) → serah terima (warisan). Lapisan refleksi yang berbeda untuk tujuan berbeda.",hint:"Apa jenis refleksi yang paling sering?"},
{n:86,type:"mcq",micro:"Kasus: anggota merasa refleksi 'menyerang' padahal fokus proses",q:"Meski fasilitator berhati-hati fokus pada proses, seorang anggota tetap merasa setiap poin adalah serangan pada dirinya. Sikap:",options:["Menyebutnya terlalu sensitif di depan tim","Bicara berdua setelahnya: dengarkan perasaannya, jelaskan niat refleksi, & cari cara agar ia merasa aman ikut refleksi berikutnya (mis. ia menyampaikan poinnya tertulis dulu)","Berhenti membahas proses sama sekali"],answer:1,explain:"Sebagian orang butuh pendekatan lebih lembut atau ruang berbeda. Menangani ini secara pribadi menjaga refleksi tetap jalan untuk semua.",hint:"Bicara berdua + cari cara ia merasa aman, atau berhenti membahas / mempermalukan?"},
{n:87,type:"tf",micro:"Refleksi menutup lingkaran belajar",q:"Benar atau Salah: Refleksi tim baru benar-benar berguna bila 'lingkarannya tertutup' — perubahan yang disepakati benar-benar diterapkan di proyek berikutnya & dicek kembali, bukan sekadar dibicarakan lalu dilupakan.",answer:true,explain:"Menyepakati perubahan adalah setengah pekerjaan. Menerapkannya & mengeceknya adalah setengah yang membuat refleksi bernilai.",hint:"Lingkaran harus tertutup (diterapkan & dicek), atau cukup dibicarakan?"},
{n:88,type:"mcq",micro:"Kasus: refleksi & anggota yang tidak hadir",q:"Beberapa anggota tidak bisa hadir sesi refleksi. Sikap:",options:["Anggap mereka setuju apa pun hasilnya","Sengaja menjadwalkan saat mereka tidak bisa","Kumpulkan masukan mereka lebih dulu (tertulis / singkat), bagikan hasil refleksi ke mereka setelahnya, & minta tanggapan — jangan membuat keputusan besar tentang cara kerja tim tanpa suara mereka"],answer:2,explain:"Refleksi menghasilkan perubahan cara kerja yang memengaruhi semua. Yang tidak hadir tetap perlu didengar.",hint:"Kumpulkan masukan + bagikan hasil + minta tanggapan, atau anggap setuju?"},
{n:89,type:"mcq",micro:"Kasus: refleksi yang menemukan tim tidak cocok",q:"Refleksi menyimpulkan bahwa komposisi/dinamika tim ini memang sulit (bukan sekadar proses yang bisa diperbaiki). Sikap:",options:["Akui dengan jujur; bahas apa yang masih bisa diperbaiki untuk sisa waktu bersama; & bila memungkinkan, sampaikan pelajaran ini agar pembentukan tim berikutnya lebih baik","Berpura-pura semuanya bisa diperbaiki dengan proses","Salahkan satu-dua orang"],answer:0,explain:"Kadang refleksi jujur menemukan bahwa masalahnya struktural. Mengakuinya (tanpa kambing hitam) lebih baik daripada terus menambal.",hint:"Akui jujur + perbaiki yang bisa + pelajaran untuk pembentukan tim, atau pura-pura / menyalahkan?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu ketua tim yang akan mengerjakan serangkaian proyek sepanjang semester (bukan satu proyek). Kamu ingin menjadikan refleksi & evaluasi sebagai kebiasaan tim yang benar-benar membuat tim membaik dari proyek ke proyek. Rancang sistem refleksi tim untuk sepanjang semester. Minimal 6 elemen konkret dengan alasan.",sample:"(1) Refleksi TENGAH tiap proyek (15 menit): tim mengecek 'apakah kita di jalur? apa yang menghambat sekarang? apa yang perlu disesuaikan?'. Alasan: menyelamatkan proyek yang menyimpang selagi masih ada waktu, bukan hanya belajar setelah terlambat. (2) Refleksi AKHIR tiap proyek (20 menit) dengan struktur tetap: aturan (fokus proses, semua bicara) → tiap orang sebut 1 hal baik + 1 hal menghambat (bergiliran) → kelompokkan & pilih 1-2 prioritas → perubahan konkret + penanggung jawab + kapan mulai → apresiasi kontribusi spesifik tiap orang. Alasan: struktur yang sama tiap kali membuat refleksi cepat, adil, & menghasilkan aksi. (3) CATATAN REFLEKSI tertulis di satu dokumen bersama: tiap refleksi menambah entri berisi tanggal, pelajaran, perubahan yang disepakati, & penanggung jawab. Alasan: pelajaran tidak menguap & bisa dilacak. (4) PENGECEKAN di awal & tengah proyek berikutnya: buka catatan refleksi sebelumnya — 'perubahan yang kita sepakati sudah dijalankan belum? membantu nggak?'. Alasan: menutup lingkaran belajar; tanpa ini refleksi hanya jadi obrolan. (5) Refleksi DIRI singkat: sebelum refleksi tim, tiap anggota menjawab untuk diri sendiri 'apakah aku menepati bagianku? membantu? mendengar? apa 1 hal yang akan kuperbaiki?' — dibagikan seperlunya. Alasan: menangkap perbaikan pribadi yang tidak nyaman disebut orang lain di forum. (6) Aku sebagai ketua MEMODELKAN dengan mengakui kekuranganku sendiri lebih dulu di tiap refleksi. Alasan: membuat semua merasa aman jujur. (7) Setiap 2 bulan, refleksi lebih dalam tentang tim itu sendiri: apakah cara kita berkomunikasi, membagi tugas, & mengambil keputusan sudah sehat? Alasan: menangkap pola & masalah struktural yang lolos dari refleksi per proyek. (8) Aturan: refleksi selalu fokus pada proses & perbaikan, bukan menyalahkan orang; siapa pun yang merasa refleksi jadi serangan bisa menyampaikannya & kita sesuaikan caranya.",explain:"Jawaban baik memuat minimal 6 elemen konkret dengan alasan: refleksi tengah + akhir tiap proyek dengan struktur tetap, catatan refleksi tertulis di dokumen bersama, pengecekan penerapan di proyek berikutnya (menutup lingkaran), refleksi diri singkat, ketua memodelkan mengakui kekurangan, refleksi lebih dalam berkala tentang tim, aturan fokus proses + jalur bila ada yang merasa diserang.",hint:"Sistem: refleksi tengah + akhir berstruktur, catatan tertulis, pengecekan penerapan (tutup lingkaran), refleksi diri, ketua memodelkan, refleksi mendalam berkala, aturan fokus-proses."},
{n:91,type:"mcq",micro:"Kasus: refleksi & tekanan waktu",q:"Proyek berikutnya sudah dekat & tim tergoda melewatkan refleksi proyek yang baru selesai. Sikap:",options:["Tunda sampai akhir semester","Lakukan refleksi singkat sekarang (bahkan 5-10 menit) — pelajaran paling segar sekarang; kalau dilewatkan, detail hilang & kesalahan yang sama terbawa ke proyek berikutnya","Lewatkan saja, tidak ada waktu"],answer:1,explain:"Refleksi singkat yang tepat waktu jauh lebih berharga daripada refleksi panjang yang tertunda sampai lupa. Jangan bawa kesalahan yang sama ke proyek berikut.",hint:"Refleksi singkat sekarang, atau lewatkan / tunda lama?"},
{n:92,type:"tf",micro:"Refleksi melayani hasil & orang",q:"Benar atau Salah: Refleksi tim yang baik menghasilkan dua hal: tim yang bekerja lebih efektif dari proyek ke proyek, DAN anggota yang merasa didengar, dihargai, & tumbuh — bukan yang merasa dihakimi.",answer:true,explain:"Refleksi yang membuat tim lebih efektif tapi anggotanya benci ikut refleksi tidak berkelanjutan. Butuh keduanya.",hint:"Tim efektif + anggota tumbuh & dihargai, atau salah satu?"},
{n:93,type:"mcq",micro:"Kasus: menyeimbangkan kritik & apresiasi",q:"Sebuah refleksi hampir seluruhnya berisi kritik & sangat sedikit apresiasi. Risikonya:",options:["Tidak ada risiko, kritik yang penting","Tim jadi terlalu percaya diri","Anggota keluar merasa lelah & tidak dihargai, & mulai menghindari atau tidak serius menghadapi refleksi berikutnya"],answer:2,explain:"Refleksi harus tetap terasa membangun. Menyebut kekuatan & mengapresiasi usaha menjaganya sebagai kebiasaan yang tim mau lakukan.",hint:"Anggota lelah & menghindari refleksi, atau tak ada risiko?"},
{n:94,type:"mcq",micro:"Kasus: refleksi diri yang terlalu keras pada diri sendiri",q:"Saat refleksi diri, seorang anggota terlalu keras menyalahkan diri sendiri atas segala hal. Sikap tim:",options:["Bantu ia melihat lebih seimbang: sebut juga kontribusi baiknya, & ingatkan bahwa banyak masalah adalah kegagalan proses tim bersama, bukan kesalahan satu orang","Setuju bahwa itu memang semua salahnya","Abaikan"],answer:0,explain:"Refleksi diri yang sehat itu jujur tapi adil pada diri sendiri. Menyalahkan diri berlebihan tidak membantu perbaikan & bisa merugikan kesejahteraan.",hint:"Bantu lihat seimbang + akui kontribusi baik + kegagalan proses bersama, atau setuju semua salahnya / abaikan?"},
{n:95,type:"tf",micro:"Refleksi = kebiasaan, bukan kejadian sekali",q:"Benar atau Salah: Manfaat terbesar refleksi datang dari satu sesi refleksi besar yang dilakukan sekali di akhir; refleksi kecil yang sering hanya membuang waktu.",answer:false,explain:"Sebaliknya, manfaat terbesar datang dari menjadikan refleksi KEBIASAAN rutin (tengah + akhir tiap proyek + pengecekan penerapan). Perbaikan bertahap dari banyak refleksi kecil jauh melampaui satu refleksi besar yang jarang.",hint:"Kebiasaan rutin, atau satu sesi besar sesekali?"},
{n:96,type:"mcq",micro:"Kasus: memulai kebiasaan refleksi di timmu",q:"Cara termudah mulai membangun kebiasaan refleksi di kelompok berikutnya:",options:["Berharap tim membaik sendiri tanpa refleksi","Di akhir proyek berikutnya, usulkan 10 menit: tiap orang sebut 1 hal yang oke + 1 hal yang bisa lebih baik, lalu sepakati 1 perubahan untuk lain kali & tuliskan","Menunggu tim yang lebih dewasa"],answer:1,explain:"Kebiasaan besar dimulai dari satu sesi kecil yang sederhana & menghasilkan. Setelah tim merasakan manfaatnya, refleksi berikutnya lebih mudah.",hint:"Usulkan 10 menit sederhana + 1 perubahan tertulis, atau menunggu / berharap?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti refleksi & evaluasi tim:",options:["Refleksi hanya perlu kalau proyek gagal","Refleksi = mencari siapa yang paling salah","Tinjau cara kerja tim secara rutin (tengah + akhir), fokus pada proses bukan menyalahkan orang, seimbangkan apresiasi & kritik, dengar semua, hasilkan 1-2 perubahan konkret + penanggung jawab, tulis & terapkan di proyek berikutnya, lalu cek — perbaikan bertahap yang konsisten"],answer:2,explain:"Ringkasan: rutin + fokus proses + seimbang + semua didengar + 1-2 perubahan konkret + tulis & terapkan & cek + perbaikan bertahap.",hint:"Rutin, fokus proses, seimbang, semua didengar, perubahan konkret, terapkan & cek, bertahap — rangkai."},
{n:98,type:"tf",micro:"Refleksi mengubah pengalaman jadi kemampuan",q:"Benar atau Salah: Refleksi & evaluasi adalah cara sebuah tim mengubah pengalaman (baik & buruk) menjadi kemampuan yang lebih besar — tanpa refleksi, tim bisa punya banyak pengalaman tapi tidak bertambah baik.",answer:true,explain:"Pengalaman + refleksi = pembelajaran. Pengalaman tanpa refleksi = pengulangan.",hint:"Refleksi mengubah pengalaman jadi kemampuan, atau pengalaman otomatis cukup?"},
{n:99,type:"mcq",micro:"Kasus: refleksi & kesejahteraan tim",q:"Selain menilai hasil & proses, refleksi tim yang baik juga menanyakan:",options:["Apakah anggota tim merasa dihargai, tidak kelelahan berlebihan, & masih bersemangat? — karena tim yang hasilnya bagus tapi anggotanya habis & kesal tidak berkelanjutan","Hanya apakah target tercapai","Kesejahteraan bukan urusan refleksi"],answer:0,explain:"Refleksi yang hanya soal hasil melewatkan tanda-tanda kelelahan & kekecewaan yang akan merusak tim di proyek berikutnya.",hint:"Tanyakan juga kesejahteraan & semangat, atau hanya target?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi soal evaluasi tim",q:"Tulis 'aturan pribadi tentang refleksi & evaluasi tim' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",sample:"Contoh aturan pribadi: (1) Di setiap proyek tim, aku mengusulkan refleksi singkat di tengah & di akhir — karena tanpa refleksi, kesalahan yang sama terbawa terus & refleksi tengah bisa menyelamatkan proyek yang menyimpang. (2) Dalam refleksi, aku menjaga fokus pada proses & perbaikan ('sistem kita kurang X'), bukan menyalahkan orang — karena menyalahkan membuat orang defensif & menyembunyikan masalah lain kali. (3) Aku menyebut juga apa yang berjalan baik & mengapresiasi kontribusi anggota secara spesifik — karena refleksi yang hanya berisi kritik membuat orang menghindarinya. (4) Aku merefleksikan kontribusiku sendiri dengan jujur tapi adil: apakah aku menepati bagianku? membantu? mendengar? — dan memilih satu hal spesifik untuk kuperbaiki. (5) Aku mendorong tim mengakhiri refleksi dengan 1-2 perubahan konkret + penanggung jawab + kapan mulai, ditulis — karena refleksi tanpa tindakan hanya jadi sesi curhat. (6) Di awal proyek berikutnya, aku mengusulkan membuka catatan refleksi sebelumnya & mengecek apakah perubahan yang disepakati dijalankan — karena lingkaran belajar hanya bermanfaat bila ditutup. (7) Aku memperhatikan anggota yang pendiam & mendorong mereka bicara, dan aku tidak menganggap diam berarti tidak punya masukan. (8) Aku menerima masukan tentang cara kerjaku tanpa langsung defensif — karena refleksi hanya berguna bila semua bisa menerima masukan.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: usulkan refleksi tengah + akhir, jaga fokus proses bukan menyalahkan orang, sebut yang berjalan baik + apresiasi spesifik, refleksi diri jujur tapi adil, akhiri dengan 1-2 perubahan konkret + penanggung jawab tertulis, cek penerapan di proyek berikutnya (tutup lingkaran), libatkan yang pendiam, terima masukan tanpa defensif.",hint:"Ambil satu pelajaran tiap fase — refleksi tengah+akhir, fokus proses, apresiasi + kekuatan, refleksi diri adil, perubahan konkret + penanggung jawab, cek penerapan, libatkan pendiam, terima masukan — jadikan aturan 'aku akan...'."},
];
